/* Illustrative rates only. No live carrier or customs connection. */
(function(root){
const routes={west:[['regular','普船','Regular ocean',2.2,30,40],['expedited','普快','Expedited ocean',2.8,23,30],['matson','美森','Matson',3.6,16,23]],east:[['ny','直航纽约','Direct to New York',2.9,38,48],['regular','普船转卡','Regular ocean + truck',3.2,35,45],['expedited','普快转卡','Expedited ocean + truck',3.8,28,37],['matson','美森转卡','Matson + truck',4.6,22,30]]};
function zone(zip){return Number(zip[0])<=3?'east':Number(zip[0])>=8?'west':'central'}
function valid(d){if(!['fba','awd','commercial','other'].includes(d.destination))throw Error('Select a destination type');if(!d.product?.trim()||!['Shanghai','Ningbo','Shenzhen','Qingdao','Xiamen'].includes(d.origin)||!/^\d{5}$/.test(d.zip)||!/^\d{4}-\d{2}-\d{2}$/.test(d.ready)||!Number.isFinite(Date.parse(d.ready)))throw Error('Invalid shipment');for(const k of ['weight','volume','cartons','pieces'])if(!Number.isFinite(+d[k])||+d[k]<=0)throw Error('Invalid quantity');if(!Number.isInteger(+d.pieces)||!Number.isInteger(+d.cartons))throw Error('Whole counts required');if(d.deadline&&d.deadline<d.ready)throw Error('Deadline precedes cargo ready date');}
function options(d){valid(d);return zone(d.zip)==='east'?routes.east:routes.west.map(r=>zone(d.zip)==='central'?[r[0],r[1]+'转卡',r[2]+' + truck',r[3]+.6,r[4]+5,r[5]+7]:r)}
function ecommerce(d){return options(d).map(r=>{const billed=Math.ceil(Math.max(+d.weight,+d.volume*167)),freight=Math.max(100,billed*r[3]);return{id:r[0],zh:r[1],en:r[2],min:r[4],max:r[5],billed,rate:r[3],total:freight,per:freight/d.pieces,rows:[['渠道运费（含尾程）','Channel freight (delivery included)',freight]],kind:'ecom'}})}
function loadPlan(d,x){const cfg=root.FreightRules;if(!cfg)throw Error('Missing freight rules');const large=+d.volume>=cfg.fullLoadThresholdCbm,auto=x.load==='AUTO',load=auto?(large?cfg.defaultContainer:'LCL'):x.load,containers=auto?Math.max(1,Math.ceil(+d.volume/cfg.referenceCbmPerLoad)):+x.containers,delivery=x.delivery||'transload',pallets=Math.ceil(+d.volume/cfg.cbmPerPallet),trucks=Math.max(1,Math.ceil(+d.volume/cfg.referenceCbmPerLoad));return{load,containers,delivery:load==='LCL'?'transload':delivery,pallets,trucks,large,auto}} 
function traditional(d,x){valid(d);const fobTotal=Math.round(Number(x.fobUnit)*Number(d.pieces)*100)/100;if(!['AUTO','LCL','20GP','40GP','40HQ','45HQ'].includes(x.load)||!Number.isFinite(+x.fobUnit)||+x.fobUnit<=0||!Number.isFinite(fobTotal)||fobTotal<=0||!Number.isInteger(+x.containers)||+x.containers<1)throw Error('Invalid trade details');if(x.delivery&&!['direct','transload'].includes(x.delivery))throw Error('Invalid delivery mode');for(const k of ['tax','fees'])if(x[k]!==''&&(!Number.isFinite(+x[k])||+x[k]<0))throw Error('Invalid customs estimate');if(x.broker==='own'&&(!Number.isFinite(+x.brokerFee)||+x.brokerFee<0))throw Error('Invalid broker fee');const taxSummary=root.TaxEngine.calculate(d,x),lp=loadPlan(d,x),cfg=root.FreightRules,z=zone(d.zip);return options(d).map((r,i)=>{const cbm=[85,135,190,220][i],container=({'20GP':2600,'40GP':3700,'40HQ':3900,'45HQ':4600})[lp.load],ocean=lp.load==='LCL'?Math.max(1,+d.volume)*cbm:container*(1+i*.25)*lp.containers,port=lp.load==='LCL'?Math.max(95,+d.volume*28):480*lp.containers,broker=x.broker==='own'?+x.brokerFee:150,direct=lp.delivery==='direct',full=!direct&&lp.large,unitRate=direct?cfg.demoDrayageRates[z]:full?cfg.demoTruckRates[z]:cfg.demoPalletRates[z],units=direct?lp.containers:full?lp.trucks:lp.pallets,truck=unitRate*units,handling=lp.load!=='LCL'&&!direct?+d.volume*cfg.demoTransloadPerCbm:0,truckName=direct?['整柜直送（拖柜）','Container drayage']:full?['拆柜后整车派送','Truckload after transloading']:['按托派送','Pallet delivery'],rows=[['海运费','Ocean freight',ocean],['目的港费用','Destination port charges',port],['报关服务费'+(x.broker==='own'?'（客户自付）':''),'Broker fee'+(x.broker==='own'?' (paid separately)':''),broker],...(handling?[['拆柜及打托（示例）','Transloading & palletizing (demo)',handling]]:[]),[...truckName,truck],...taxSummary.rows.map(r=>r.slice(0,3))],total=rows.reduce((s,r)=>s+(r[2]??0),0);return{id:r[0],zh:r[1],en:r[2],min:r[4],max:r[5],total,landed:total+fobTotal,per:(total+fobTotal)/d.pieces,fobTotal,taxSummary,complete:taxSummary.complete,rows,kind:'trade',oceanRate:cbm,loadPlan:lp,deliveryQuote:{mode:direct?'direct':full?'ftl':'pallet',units,unitRate,total:truck}}})}
function arrival(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
root.QuoteEngine={zone,valid,ecommerce,traditional,arrival,loadPlan};if(typeof module!=='undefined')module.exports=root.QuoteEngine;
})(globalThis);
